const LANGUES_COCKPIT_V4 = Object.freeze([
  "fr",
  "en",
  "de",
  "es",
  "pt-BR",
  "it",
  "nl",
  "ja",
  "zh-CN",
]);

const OPTIONS_LANGUES_COCKPIT_V4 = Object.freeze([
  Object.freeze({ code: "fr", nom: "Français" }),
  Object.freeze({ code: "en", nom: "English" }),
  Object.freeze({ code: "de", nom: "Deutsch" }),
  Object.freeze({ code: "es", nom: "Español" }),
  Object.freeze({ code: "pt-BR", nom: "Português (Brasil)" }),
  Object.freeze({ code: "it", nom: "Italiano" }),
  Object.freeze({ code: "nl", nom: "Nederlands" }),
  Object.freeze({ code: "ja", nom: "日本語" }),
  Object.freeze({ code: "zh-CN", nom: "简体中文" }),
]);

function normaliserLangueCockpitV4(langue) {
  return LANGUES_COCKPIT_V4.includes(langue)
    ? langue
    : "fr";
}

function lireCle(objet, cle) {
  return cle
    .split(".")
    .reduce(
      (valeur, segment) =>
        valeur && typeof valeur === "object"
          ? valeur[segment]
          : undefined,
      objet,
    );
}

function interpoler(texte, variables = {}) {
  return String(texte).replace(
    /\{([a-zA-Z0-9_]+)\}/g,
    (correspondance, nom) =>
      Object.hasOwn(variables, nom)
        ? String(variables[nom])
        : correspondance,
  );
}

function traduireV4(langue, cle, variables = {}) {
  const actif = normaliserLangueCockpitV4(langue);

  const texte =
    lireCle(TRADUCTIONS_V4[actif], cle) ??
    lireCle(TRADUCTIONS_V4.fr, cle) ??
    cle;

  return interpoler(texte, variables);
}

