/*
 * SPDX-FileCopyrightText: 2026 Vincent Fournet
 * SPDX-License-Identifier: PolyForm-Noncommercial-1.0.0
 */

/**
 * Thèmes visuels de Pool Cockpit v4.
 *
 * Compatibilité volontaire avec les identifiants historiques v3 :
 * ocean, sky, night et auto.
 *
 * RÈGLE V4-THEME-001 :
 * ce module reste pur : aucun accès au DOM, au navigateur,
 * à Home Assistant ou au stockage.
 */

const THEMES_COCKPIT_V4 = Object.freeze([
  "ocean",
  "sky",
  "night",
  "auto",
]);

function normaliserThemeCockpitV4(theme) {
  return THEMES_COCKPIT_V4.includes(theme)
    ? theme
    : "ocean";
}

/**
 * Reproduit exactement la logique historique v3 :
 * auto + mode sombre => night
 * auto + mode clair  => sky
 */
function resoudreThemeCockpitV4(
  theme,
  modeSombrePrefere = false,
) {
  const normalise = normaliserThemeCockpitV4(theme);

  if (normalise !== "auto") {
    return normalise;
  }

  return modeSombrePrefere
    ? "night"
    : "sky";
}

