function v4_32TranslateMarkup(markup, language) {
  const dictionary = { ...V4_32_LABELS[language] };
  const labels = LIBELLES_ASSISTANT_V4[language];
  if (labels && language !== "fr") LIBELLES_ASSISTANT_V4.fr.forEach((key,i)=>{dictionary[key]=labels[i];});
  if (language === "fr" || !V4_32_LABELS[language] || typeof markup !== "string") return markup;
  const attributes = markup.replace(/\b(aria-label|title|placeholder)="([^"]*)"/g, (match, name, value) => dictionary[value] ? `${name}="${dictionary[value]}"` : match);
  return attributes.replace(/>([^<>]+)</g, (match, raw) => {
    const clean = raw.trim();
    const translated = dictionary[clean];
    if (!translated) return match;
    const initial = raw.slice(0, raw.indexOf(clean));
    const suffix = raw.slice(raw.indexOf(clean) + clean.length);
    return ">" + initial + translated + suffix + "<";
  });
}

