function rc4Kpi(label,value){return `<div class="rc4-kpi"><dt>${rc3Escape(label)}</dt><dd>${rc3Escape(value??'—')}</dd></div>`;}
function rc4ZoomDates(model,lang){const a=model.start+(model.end-model.start)*(model.zoom?.[0]||0)/100,b=model.start+(model.end-model.start)*(model.zoom?.[1]??100)/100;return [a,b].map(t=>new Date(t).toLocaleString(lang,{dateStyle:'short',timeStyle:'short'}));}

