function valeurAffichable(valeur, repli = "—") {
  if (valeur === null || valeur === undefined || valeur === "") {
    return repli;
  }

  return String(valeur);
}

function pourcentageScore(valeur) {
  const nombre = Number.parseFloat(
    String(valeur ?? "").replace(",", "."),
  );

  if (!Number.isFinite(nombre)) {
    return 0;
  }

  return Math.max(0, Math.min(100, nombre));
}

function nombreEtoiles(valeur) {
  const nombre = Number.parseInt(String(valeur ?? ""), 10);

  if (!Number.isFinite(nombre)) {
    return 0;
  }

  return Math.max(0, Math.min(5, nombre));
}

function normaliserEquipement(equipement = {}, langue = "fr") {
  return {
    id: valeurAffichable(equipement.id, "equipment"),
    type: valeurAffichable(equipement.type, "generic"),
    titre: valeurAffichable(
      equipement.titre,
      traduireV4(langue, "overview.defaults.equipment"),
    ),
    etat: valeurAffichable(
      equipement.etat,
      traduireV4(langue, "common.unavailable"),
    ),
    detail: valeurAffichable(equipement.detail, ""),
    actif: Boolean(equipement.actif),
    disponible: equipement.disponible !== false,
  };
}

