/**
 * Carte compacte de mesure du cockpit v4.
 *
 * Le composant ne connaît aucune mesure métier particulière.
 */
function rendreCarteMesureV4({
  libelle,
  valeur,
  unite = "",
  variante = "default",
  icone = "",
}) {
  return `
    <article class="v4-metric v4-metric--${variante}">
      <span class="v4-metric__icon" aria-hidden="true">${icone}</span>

      <span class="v4-metric__content">
        <small>${libelle}</small>
        <strong>${valeur}${unite ? `<em>${unite}</em>` : ""}</strong>
      </span>
    </article>
  `;
}

