function rendreEtoilesScoreV4(nombre = 0, langue = "fr") {
  if (nombre <= 0) {
    return "";
  }

  return `
    <div
      class="v4-score__stars"
      aria-label="${traduireV4(
        langue,
        "overview.starsAria",
        { count: nombre },
      )}"
    >
      ${"★".repeat(nombre)}
    </div>
  `;
}

function rendreHeroSyntheseV4(
  modele,
  { langue = "fr" } = {},
) {
  const actionAnalyseDisponible =
    modele.score.actionAnalyse?.disponible === true;

  return `
    <section class="v4-hero">
      <div class="v4-hero__water">
        <p class="v4-eyebrow">${traduireV4(
          langue,
          "overview.eyebrow",
        )}</p>

        <div class="v4-hero__title">
          ${rendreMarquePoolCockpitV4({
            titre: modele.piscine.titre,
            message: modele.piscine.message,
          })}

          <span class="v4-health">
            <i aria-hidden="true"></i>
            ${modele.piscine.etat}
          </span>
        </div>

        <div class="v4-hero__temperature">
          <span
            class="v4-hero__temperature-icon"
            aria-hidden="true"
          >
            ${ICONES_V4.water}
          </span>

          <div>
            <strong>
              ${modele.eau.temperature}
              <small>${modele.eau.uniteTemperature}</small>
            </strong>

            <span>${traduireV4(
              langue,
              "overview.waterTemperature",
            )}</span>
          </div>
        </div>

        <div class="v4-hero__metrics">
          ${rendreCarteMesureV4({
            libelle: "pH",
            valeur: modele.eau.ph,
            variante: "ph",
            icone: ICONES_V4.ph,
          })}

          ${rendreCarteMesureV4({
            libelle: "ORP",
            valeur: modele.eau.orp,
            unite:
              modele.eau.orp === "—"
                ? ""
                : ` ${modele.eau.uniteOrp}`,
            variante: "orp",
            icone: ICONES_V4.orp,
          })}

          ${rendreCarteMesureV4({
            libelle: traduireV4(
              langue,
              "overview.confidence",
            ),
            valeur: modele.eau.confiance,
            unite:
              modele.eau.confiance === "—"
                ? ""
                : " %",
            variante: "confidence",
            icone: ICONES_V4.confidence,
          })}
        </div>
      </div>

      <aside class="v4-score">
        <small>${traduireV4(
          langue,
          "overview.globalStatus",
        )}</small>

        <div
          class="v4-score__ring"
          style="--v4-score:${modele.score.pourcentage}"
        >
          <div>
            <strong>${modele.score.valeur}</strong>
            <span>${
              modele.score.valeur === "—"
                ? ""
                : `/${modele.score.maximum}`
            }</span>
          </div>
        </div>

        <h2>${modele.score.libelle}</h2>

        ${rendreEtoilesScoreV4(
          modele.score.etoiles,
          langue,
        )}

        ${modele.score.conseil
          ? `
            <p class="v4-score__advice">
              ${modele.score.conseil}
            </p>
          `
          : ""}

        <button
          type="button"
          class="v4-score__action"
          data-v4-action="run-analysis"
          ${actionAnalyseDisponible ? "" : "disabled"}
        >
          ${modele.score.actionAnalyse?.libelle ??
            traduireV4(langue, "overview.runAnalysis")}
        </button>

        ${modele.score.analyseSuivi ? rc5ProgressMarkup(modele.score.analyseSuivi,langue) : ""}
        <button type="button" class="v4-score__details" data-v4-view="measurements">${traduireV4(langue,"overview.analysisDetails")} →</button>

        <p class="v4-score__last">
          ${traduireV4(langue, "overview.lastAnalysis")}
          <strong>${modele.score.derniereAnalyse}</strong>
        </p>
      </aside>
    </section>
  `;
}

