/**
 * Carte d'équipement générique de la vue d'ensemble v4.
 *
 * RÈGLE V4-EQUIP-002 :
 * le renderer ne contient aucune liste fermée de matériels.
 *
 * RÈGLE V4-EQUIP-003 :
 * l'état fonctionnel est fourni par le modèle de vue. Le composant ne déduit
 * jamais lui-même si un équipement est en marche, en veille ou indisponible.
 */
function rendreCarteEquipementV4(equipement) {
  const classeEtat = equipement.actif
    ? "is-active"
    : "is-idle";

  return `
    <article
      class="v4-equipment-card ${classeEtat}"
      data-equipment-type="${equipement.type}"
    >
      <div class="v4-equipment-card__header">
        <span class="v4-equipment-card__icon" aria-hidden="true">
          ${iconeEquipementV4(equipement.type)}
        </span>

        <span class="v4-equipment-card__badge">
          <i aria-hidden="true"></i>
          ${equipement.etat}
        </span>
      </div>

      <div class="v4-equipment-card__body">
        <strong>${equipement.titre}</strong>

        ${equipement.detail
          ? `<p>${equipement.detail}</p>`
          : ""}
      </div>
    </article>
  `;
}

