function rendreVueEnsembleCockpitV4(
  source = {},
  { langue = "fr" } = {},
) {
  const actif = normaliserLangueCockpitV4(langue);
  const lib = LIBELLES_STATUT_V4[actif] || LIBELLES_STATUT_V4.fr;
  const modele = construireModeleVueEnsembleV4(
    source,
    { langue: actif },
  );

  return `
    <section
      class="v4-view v4-overview"
      data-v4-view-panel="overview"
      aria-label="${traduireV4(actif, "overview.aria")}"
    >

      ${rendreVueEnsembleMobileV4(
        modele,
        { langue: actif },
      )}

      ${rendreHeroSyntheseV4(modele, { langue: actif })}

      ${modele.equipements.length
        ? `
          <section class="v4-overview__section">
            <header class="v4-overview__section-header">
              <div>
                <small>${traduireV4(
                  actif,
                  "overview.equipmentKicker",
                )}</small>

                <h2>${traduireV4(
                  actif,
                  "overview.equipmentTitle",
                )}</h2>

                <p>${traduireV4(
                  actif,
                  "overview.equipmentSubtitle",
                )}</p>
              </div>
            </header>

            <div class="v4-equipment-grid">
              ${modele.equipements
                .map(rendreCarteEquipementV4)
                .join("")}
            </div>
          </section>
        `
        : ""}

      <section class="v4-overview__status" aria-label="${lib[7]}">
        <div class="v4-overview__status-card">
          <small>${lib[0]}</small>
          <strong>${modele.synthese.mesures.actifs === null || modele.synthese.mesures.total === null ? "—" : `${modele.synthese.mesures.actifs} / ${modele.synthese.mesures.total} ${lib[1]}`}</strong>
          <span>${modele.synthese.mesures.source}</span>
        </div>
        <div class="v4-overview__status-card">
          <small>${lib[2]}</small>
          <strong>${modele.synthese.filtration.etat === "on" ? lib[3] : modele.synthese.filtration.etat === "off" ? lib[4] : lib[5]}</strong>
          <span>${lib[6]}</span>
        </div>
        <div class="v4-overview__status-card">
          <small>${lib[7]}</small>
          <strong>${modele.synthese.programmation.mode === "automatic" ? lib[8] : modele.synthese.programmation.mode === "manual" ? lib[9] : lib[10]}</strong>
          <span>${rc3Text(actif,modele.synthese.programmation.mode === "automatic" ? "adaptive" : modele.synthese.programmation.mode === "manual" ? "manual" : "unknownSchedule")}</span>
        </div>
      </section>

      <nav class="v4-quick-controls" aria-label="${v4OverviewExternal(actif,24)}">
        <div class="v4-quick-controls__heading">
          <span class="v4-quick-controls__heading-icon" aria-hidden="true">⚡</span>
          <span class="v4-quick-controls__heading-label">${v4OverviewExternal(actif,12)}</span>
          <span class="v4-quick-controls__heading-note">${v4OverviewExternal(actif,13)}</span>
        </div>
        <div class="v4-quick-controls__grid">
          ${[
            ["pompe", v4OverviewExternal(actif,14), "pump"],
            ["pac", v4OverviewExternal(actif,15), "pac"],
            ["eclairage", v4OverviewExternal(actif,16), "light"],
          ].map(([cle,nom,cible])=>{
            const etat=modele.synthese.raccourcis?.[cle]||{};
            const connu=["on","off"].includes(etat.etat);
            const estAllume=etat.etat==="on";
            const permis=connu&&etat.configure&&etat.autorise&&modele.synthese.raccourcis.roleAutorise;
            const raison=permis?v4OverviewExternal(actif,21):cle==="pompe"?v4OverviewExternal(actif,22):v4OverviewExternal(actif,23);
            const label=estAllume?v4OverviewExternal(actif,20):v4OverviewExternal(actif,19);
            return `<div class="v4-quick-control ${estAllume?"is-on":""}">
              <button type="button" class="v4-quick-control__action" data-v4-quick-control="${cible}:${estAllume?"off":"on"}" ${permis?"":"disabled"} aria-label="${label} ${nom}" title="${permis?label+" "+nom:raison}">
                <svg viewBox="0 0 24 24" aria-hidden="true" focusable="false"><path d="M12 2v10M7 5a8 8 0 1 0 10 0" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round"/></svg>
              </button>
              <span class="v4-quick-control__identity"><strong>${nom}</strong><small>${connu?(estAllume?v4OverviewExternal(actif,17):v4OverviewExternal(actif,18)):traduireV4(actif,"common.unavailable")}</small></span>
            </div>`;
          }).join("")}
        </div>
      </nav>
      <div class="v4-overview__context">
        ${rendreMeteoV4(modele.meteo, { langue: actif })}
        ${rendreProchaineActionV4(
          modele.prochaineAction,
          { langue: actif },
        )}
      </div>
    </section>
  `;
}

