function estRenseignee(valeur) {
  return valeur !== null &&
    valeur !== undefined &&
    valeur !== "";
}

function valeurAffichableEau(valeur, repli = "—") {
  return estRenseignee(valeur)
    ? String(valeur)
    : repli;
}

function normaliserMesure({
  id,
  libelle,
  valeur,
  unite = "",
  optionnelle = false,
}) {
  return {
    id,
    libelle,
    valeur: valeurAffichableEau(valeur),
    unite: valeurAffichableEau(unite, ""),
    disponible: estRenseignee(valeur),
    optionnelle,
  };
}

function normaliserAction(
  action = {},
  libelleParDefaut,
) {
  return {
    libelle: valeurAffichableEau(
      action.libelle,
      libelleParDefaut,
    ),
    disponible: Boolean(action.disponible),
  };
}

function construireModeleEauV4(
  source = {},
  { langue = "fr" } = {},
) {
  const actif = normaliserLangueCockpitV4(langue);
  const eau = source.eau ?? {};
  const analyse = source.analyse ?? {};
  const traitement = source.traitement ?? {};

  const mesures = [
    normaliserMesure({
      id: "temperature",
      libelle: traduireV4(
        actif,
        "water.metrics.temperature",
      ),
      valeur: eau.temperature,
      unite: valeurAffichableEau(
        eau.uniteTemperature,
        "°C",
      ),
    }),

    normaliserMesure({
      id: "ph",
      libelle: "pH",
      valeur: eau.ph,
    }),

    normaliserMesure({
      id: "orp",
      libelle: "ORP",
      valeur: eau.orp,
      unite: valeurAffichableEau(
        eau.uniteOrp,
        "mV",
      ),
    }),
  ];

  if (estRenseignee(eau.conductivite)) {
    mesures.push(
      normaliserMesure({
        id: "conductivite",
        libelle: traduireV4(
          actif,
          "water.metrics.conductivity",
        ),
        valeur: eau.conductivite,
        unite: valeurAffichableEau(
          eau.uniteConductivite,
          "µS/cm",
        ),
        optionnelle: true,
      }),
    );
  }

  return {
    synthese: {
      etat: valeurAffichableEau(
        eau.etat,
        traduireV4(
          actif,
          "water.defaults.stateUnavailable",
        ),
      ),
      message: valeurAffichableEau(
        eau.message,
        traduireV4(
          actif,
          "water.defaults.monitoring",
        ),
      ),
    },

    mesures,

    confiance: {
      valeur: valeurAffichableEau(eau.confiance),
      libelle: valeurAffichableEau(
        eau.libelleConfiance,
        traduireV4(
          actif,
          "water.defaults.measurementConfidence",
        ),
      ),
      source: valeurAffichableEau(
        eau.sourceMesure,
        traduireV4(
          actif,
          "water.defaults.sourceUnknown",
        ),
      ),
    },

    analyse: {
      score: valeurAffichableEau(analyse.score),
      maximum: valeurAffichableEau(
        analyse.maximum,
        "100",
      ),
      libelle: valeurAffichableEau(
        analyse.libelle,
        traduireV4(
          actif,
          "water.defaults.analysisUnavailable",
        ),
      ),
      conseil: valeurAffichableEau(
        analyse.conseil,
        "",
      ),
      derniereAnalyse: valeurAffichableEau(
        analyse.derniereAnalyse,
        traduireV4(
          actif,
          "water.defaults.noAnalysis",
        ),
      ),
      action: normaliserAction(
        analyse.action,
        traduireV4(
          actif,
          "water.defaults.runAnalysis",
        ),
      ),
    },

    traitement: {
      etat: valeurAffichableEau(
        traitement.etat,
        traduireV4(
          actif,
          "water.defaults.noRecommendation",
        ),
      ),
      recommandation: valeurAffichableEau(
        traitement.recommandation,
        "",
      ),
      produit: valeurAffichableEau(
        traitement.produit,
        "",
      ),
      dosage: valeurAffichableEau(
        traitement.dosage,
        "",
      ),
      action: normaliserAction(
        traitement.action,
        traduireV4(
          actif,
          "water.defaults.viewTreatment",
        ),
      ),
    },
  };
}

