function rendreMesureEauV4(
  mesure,
  langue = "fr",
) {
  const unite =
    mesure.valeur !== "—" && mesure.unite
      ? `<span class="v4-water-metric__unit">${mesure.unite}</span>`
      : "";

  /*
   * Une mesure disponible n'a pas besoin d'annoncer "Disponible".
   * L'état n'est montré que lorsqu'une anomalie existe.
   */
  const disponibilite = mesure.disponible
    ? ""
    : `
      <span class="v4-water-metric__availability">
        ${traduireV4(langue, "common.unavailable")}
      </span>
    `;

  return `
    <article
      class="v4-water-metric${mesure.disponible
        ? ""
        : " is-unavailable"}"
      data-v4-water-metric="${mesure.id}"
    >
      <small>${mesure.libelle}</small>
      <strong>${mesure.valeur}${unite}</strong>
      ${disponibilite}
    </article>
  `;
}

function rendreActionEauV4(
  action,
  identifiant,
) {
  return `
    <button
      type="button"
      class="v4-water__action"
      data-v4-action="${identifiant}"
      ${action.disponible ? "" : "disabled"}
    >${action.libelle}</button>
  `;
}

