const rc3Fmt=(v,unit,lang)=>Number.isFinite(v)?`${v.toLocaleString(lang,{maximumFractionDigits:2})} ${rc3Escape(unit)}`:'—';
function rc3SeriesName(s,lang){return `${['temperature','outside','filtration','pac','analysis'].includes(s.metric)?(s.metric==='analysis'?traduireV4(lang,'overview.runAnalysis'):rc3Text(lang,s.metric==='temperature'?'water':s.metric)):s.metric==='ph'?'pH':'ORP'}${s.name?' · '+rc3Escape(s.name):''}`;}
