 const filtered=visible.map(s=>({...s,points:s.points.filter(p=>p.timestamp>=start&&p.timestamp<=end)}));
 const units=[...new Set(filtered.map(s=>s.unit))];const h=Math.max(180,units.length*120),viewport=model.viewportWidth||1440,media=model.mediaWidth||viewport,w=Math.max(250,Math.round(model.compare?viewport-80:media>1100?(viewport-112)/3:viewport-80)),left=55,right=16;
