  if(validRef)drawing+=`<rect x="${left}" y="${y(ref[1])}" width="${w-left-right}" height="${y(ref[0])-y(ref[1])}" fill="#94a3b8" opacity=".18"><title>${t('reference')} : ${ref[0]} — ${ref[1]} ${rc3Escape(unit)}</title></rect><path d="M${left},${y(ref[0])}H${w-right}M${left},${y(ref[1])}H${w-right}" stroke="currentColor" stroke-dasharray="8 4" opacity=".55"/>`;
