   if(s.kind==='state'&&prev)path+=`H${w-right}`;
   drawing+=`<path d="${path}" stroke="${s.color}" stroke-width="2.5" fill="none" stroke-dasharray="${s.dash||''}"/>`;
   for(const p of pts.filter(p=>p.value!==null).filter((_,i,a)=>a.length<80||i%Math.ceil(a.length/80)===0))drawing+=`<circle cx="${x(p.timestamp)}" cy="${y(p.value)}" r="2.5" fill="${s.color}"><title>${rc3SeriesName(s,lang)} · ${rc3Escape(new Date(p.originalTimestamp||p.timestamp).toLocaleString(lang))} · ${rc3Fmt(p.value,s.unit,lang)}</title></circle>`;
