 if(model.showEvents!==false)for(const event of (model.events||[]).filter(e=>e.timestamp>=start&&e.timestamp<=end))drawing+=`<path d="M${x(event.timestamp)},4v8" stroke="#fbbf24" stroke-dasharray="2 6" opacity=".5"><title>${rc3Escape(event.label)}</title></path>`;
