 const groups=m.compare?[{id:'comparison',title:t('compare'),data:series}]:[{id:'temperature',title:t('water'),data:series.filter(s=>['temperature','outside','pac'].includes(s.metric))},{id:'ph',title:'pH',data:series.filter(s=>s.metric==='ph')},{id:'orp',title:'ORP',data:series.filter(s=>['orp','filtration'].includes(s.metric))}];
