/**
 * Finition visuelle premium de Pool Cockpit v4.
 *
 * Ce module ne modifie ni la structure ni la typographie.
 * Il apporte uniquement profondeur, lumière et contraste.
 *
 * RÈGLE V4-PREMIUM-001 :
 * les effets lumineux restent concentrés sur les informations importantes.
 *
 * RÈGLE V4-PREMIUM-002 :
 * aucun effet décoratif ne doit nuire à la lisibilité des données.
 *
 * RÈGLE V4-PREMIUM-003 :
 * la profondeur est obtenue principalement par contraste, bordures
 * translucides et ombres, jamais par des animations envahissantes.
 */

const STYLES_PREMIUM_V4 = `
  /* ==========================================================
   * NAVIGATION
   * ========================================================== */

  .v4-navigation{
    box-shadow:
      0 14px 38px rgba(4,43,87,.11),
      inset 0 1px 0 rgba(255,255,255,.48);
  }

  .v4-navigation__item.is-active{
    color:#fff;
    background:
      linear-gradient(
        135deg,
        rgba(70,128,239,.96),
        rgba(75,199,228,.82)
      );
    box-shadow:
      0 9px 24px rgba(21,108,203,.27),
      0 0 20px rgba(78,205,239,.10),
      inset 0 1px 0 rgba(255,255,255,.34);
    text-shadow:0 1px 7px rgba(0,55,110,.20);
  }


  /* ==========================================================
   * HERO
   *
   * Le côté gauche reçoit davantage de profondeur afin que les
   * valeurs principales ressortent, sans masquer le paysage.
   * ========================================================== */

  .v4-hero{
    border-color:rgba(116,224,255,.36);

    background:
      linear-gradient(
        100deg,
        rgba(5,35,84,.38) 0%,
        rgba(8,55,105,.22) 35%,
        rgba(15,105,157,.08) 67%,
        rgba(2,35,76,.13) 100%
      );

    box-shadow:
      0 26px 60px rgba(0,31,72,.23),
      0 0 30px rgba(53,190,238,.045),
      inset 0 1px 0 rgba(255,255,255,.20),
      inset 0 0 50px rgba(22,168,231,.035);
  }

  /* ----------------------------------------------------------
   * Identité Pool Cockpit
   *
   * Le logo possède déjà son propre rendu glossy/lumineux :
   * aucun carré ou fond artificiel n'est ajouté autour.
   * ---------------------------------------------------------- */

  .v4-hero__brand{
    display:flex;
    align-items:center;
    min-width:0;
    gap:13px;
  }

  .v4-hero__brand-logo{
    display:block;
    width:60px;
    height:60px;
    flex:0 0 60px;
    object-fit:contain;

    filter:
      drop-shadow(0 8px 15px rgba(0,49,118,.22))
      drop-shadow(0 0 12px rgba(77,207,255,.10));
  }

  .v4-hero__brand-copy{
    min-width:0;
  }

  .v4-hero__temperature strong{
    text-shadow:
      0 7px 24px rgba(0,25,65,.25),
      0 0 32px rgba(112,223,255,.075);
  }


  /* ==========================================================
   * MESURES ESSENTIELLES
   * ========================================================== */

  .v4-metric{
    border-color:rgba(111,221,255,.31);

    background:
      radial-gradient(
        circle at 10% 24%,
        rgba(69,198,240,.075),
        transparent 31%
      ),
      linear-gradient(
        145deg,
        rgba(5,48,106,.63),
        rgba(10,76,130,.40)
      );

    box-shadow:
      0 14px 31px rgba(0,31,73,.17),
      inset 0 1px 0 rgba(255,255,255,.15),
      inset 0 0 24px rgba(50,195,242,.05);
  }

  .v4-metric__icon{
    border-color:rgba(122,230,255,.48);

    background:
      radial-gradient(
        circle at 35% 30%,
        rgba(103,223,255,.22),
        rgba(35,134,203,.15) 52%,
        rgba(8,61,121,.20)
      );

    box-shadow:
      inset 0 1px 0 rgba(255,255,255,.22),
      0 0 11px rgba(90,220,255,.22),
      0 0 24px rgba(58,196,242,.13);
  }

  .v4-metric__icon svg{
    filter:
      drop-shadow(0 0 5px rgba(137,235,255,.40));
  }


  /* ==========================================================
   * SCORE GLOBAL
   *
   * Le score reste le point focal secondaire de l'écran,
   * mais utilise le même verre bleu que le reste du cockpit.
   * ========================================================== */

  .v4-score{
    border-color:rgba(126,226,255,.38);

    background:
      radial-gradient(
        circle at 50% 22%,
        rgba(76,179,230,.18),
        transparent 42%
      ),
      linear-gradient(
        150deg,
        rgba(7,48,101,.80),
        rgba(13,75,124,.62)
      );

    box-shadow:
      0 22px 48px rgba(0,26,66,.24),
      0 0 26px rgba(66,202,244,.055),
      inset 0 1px 0 rgba(255,255,255,.17),
      inset 0 0 34px rgba(41,171,228,.07);
  }

  .v4-score__ring{
    width:120px;
    height:120px;

    outline:2px solid rgba(217,248,255,.27);
    outline-offset:5px;

    filter:
      drop-shadow(0 0 7px rgba(155,237,255,.30))
      drop-shadow(0 0 16px rgba(66,206,255,.18));

    box-shadow:
      0 0 0 1px rgba(211,248,255,.17),
      0 0 18px rgba(93,223,255,.20),
      0 0 34px rgba(57,191,247,.11),
      inset 0 0 21px rgba(62,169,235,.11);
  }

  .v4-score__ring strong{
    text-shadow:
      0 2px 10px rgba(0,25,70,.22),
      0 0 17px rgba(112,229,255,.12);
  }

  .v4-score__stars{
    margin-top:8px;
    color:#ffe36c;
    text-shadow:
      0 0 8px rgba(255,211,75,.22),
      0 2px 8px rgba(0,38,82,.20);
  }

  .v4-score__advice{
    max-width:235px;
    margin:10px auto 0;
    color:rgba(238,248,255,.82);
  }

  .v4-score__action{
    width:100%;
    min-height:39px;
    margin-top:13px;
    padding:0 14px;

    border:1px solid rgba(170,235,255,.26);
    border-radius:13px;

    color:#fff;

    background:
      linear-gradient(
        135deg,
        rgba(63,153,243,.96),
        rgba(78,104,241,.94)
      );

    box-shadow:
      0 10px 22px rgba(28,82,193,.22),
      inset 0 1px 0 rgba(255,255,255,.23);

    cursor:pointer;

    transition:
      transform .16s ease,
      box-shadow .18s ease;
  }

  .v4-score__action:hover:not(:disabled){
    transform:translateY(-1px);

    box-shadow:
      0 13px 27px rgba(28,82,193,.28),
      0 0 18px rgba(69,186,246,.09),
      inset 0 1px 0 rgba(255,255,255,.27);
  }

  .v4-score__action:active:not(:disabled){
    transform:translateY(0);
  }

  .v4-score__action:disabled{
    opacity:.42;
    cursor:default;
  }

  .v4-score__last{
    width:100%;
    margin-top:12px !important;
    padding-top:10px;

    border-top:1px solid rgba(214,243,255,.12);
  }


  /* ==========================================================
   * CONTENEUR ÉQUIPEMENTS
   *
   * Le panneau parent laisse davantage apparaître l'eau.
   * Les cartes internes assurent ensuite la profondeur.
   * ========================================================== */

  .v4-overview__section{
    border-color:rgba(137,229,255,.18);

    background:
      linear-gradient(
        145deg,
        rgba(7,45,92,.37),
        rgba(17,94,142,.20)
      );

    box-shadow:
      0 17px 42px rgba(0,30,69,.12),
      inset 0 1px 0 rgba(255,255,255,.11);

    backdrop-filter:blur(12px) saturate(116%);
  }


  /* ==========================================================
   * CARTES ÉQUIPEMENTS
   * ========================================================== */

  .v4-equipment-card{
    border-color:rgba(112,224,255,.28);

    background:
      radial-gradient(
        circle at 14% 16%,
        rgba(72,205,246,.095),
        transparent 34%
      ),
      linear-gradient(
        145deg,
        rgba(5,40,90,.70),
        rgba(10,68,120,.49)
      );

    box-shadow:
      0 16px 34px rgba(0,28,70,.19),
      inset 0 1px 0 rgba(255,255,255,.13),
      inset 0 0 25px rgba(61,193,239,.035);

    transition:
      transform .18s ease,
      border-color .18s ease,
      box-shadow .18s ease;
  }

  .v4-equipment-card:hover{
    transform:translateY(-2px);

    border-color:rgba(126,232,255,.43);

    box-shadow:
      0 21px 42px rgba(0,27,69,.23),
      0 0 24px rgba(66,205,247,.095),
      inset 0 1px 0 rgba(255,255,255,.16);
  }

  .v4-equipment-card__icon{
    border-color:rgba(121,230,255,.42);

    background:
      radial-gradient(
        circle at 35% 28%,
        rgba(95,219,255,.19),
        rgba(29,123,190,.13) 55%,
        rgba(5,53,110,.17)
      );

    box-shadow:
      inset 0 1px 0 rgba(255,255,255,.18),
      0 0 12px rgba(93,221,255,.18),
      0 0 22px rgba(65,199,244,.10);
  }

  .v4-equipment-card__icon svg{
    filter:
      drop-shadow(0 0 5px rgba(131,234,255,.34));
  }


  /* ==========================================================
   * MÉTÉO / PROCHAINE ACTION
   * ========================================================== */

  .v4-context-card{
    border-color:rgba(116,224,255,.25);

    background:
      linear-gradient(
        145deg,
        rgba(5,47,100,.58),
        rgba(12,78,129,.38)
      );

    box-shadow:
      0 16px 34px rgba(0,30,71,.16),
      inset 0 1px 0 rgba(255,255,255,.13);
  }

  .v4-context-card__icon{
    border-color:rgba(123,230,255,.38);

    box-shadow:
      inset 0 1px 0 rgba(255,255,255,.17),
      0 0 11px rgba(92,218,255,.17),
      0 0 21px rgba(68,201,245,.09);
  }


  /* ==========================================================
   * RESPONSIVE
   * ========================================================== */

  @media(max-width:760px){
    .v4-score__ring{
      width:108px;
      height:108px;
      outline-offset:4px;
    }

    .v4-equipment-card:hover{
      transform:none;
    }
  }

  /* ==========================================================
   * VUE D'ENSEMBLE DESKTOP COMPACTE
   *
   * RÈGLE V4-OVERVIEW-001 :
   * sur un écran desktop standard, les informations essentielles
   * de la vue d'ensemble doivent rester visibles sans défilement.
   *
   * On réduit les espaces structurels, jamais les informations.
   * ========================================================== */

  @media(min-width:1000px) and (min-height:760px){

    .v4-overview{
      gap:12px;
    }

    .v4-hero{
      padding:18px 20px;
      gap:16px;
      grid-template-columns:minmax(0,1fr) 238px;
    }

    .v4-hero__brand{
      gap:11px;
    }

    .v4-hero__brand-logo{
      width:53px;
      height:53px;
      flex-basis:53px;
    }

    .v4-eyebrow{
      margin-bottom:7px;
    }

    .v4-hero__title p{
      margin-top:4px;
    }

    .v4-hero__temperature{
      margin-top:14px;
    }

    .v4-hero__temperature>div>span{
      margin-top:7px;
    }

    .v4-hero__metrics{
      margin-top:14px;
      gap:9px;
    }

    .v4-metric{
      min-height:58px;
      padding:9px 12px;
    }

    .v4-metric__icon{
      width:38px;
      height:38px;
    }

    .v4-score{
      padding:15px 16px;
      border-radius:23px;
    }

    .v4-score__ring{
      width:108px;
      height:108px;
      margin:9px 0 7px;
      outline-offset:4px;
    }

    .v4-score__stars{
      margin-top:5px;
    }

    .v4-score__advice{
      margin-top:7px;
      line-height:1.32;
    }

    .v4-score__action{
      min-height:34px;
      margin-top:9px;
    }

    .v4-score__last{
      margin-top:8px !important;
      padding-top:7px;
    }

    .v4-overview__section{
      padding:13px 14px;
      border-radius:22px;
    }

    .v4-overview__section-header{
      margin-bottom:10px;
    }

    .v4-overview__section-header p{
      margin-top:2px;
    }

    .v4-equipment-grid{
      gap:9px;
    }

    .v4-equipment-card{
      min-height:98px;
      padding:11px 12px;
      border-radius:18px;
    }

    .v4-equipment-card__icon{
      width:38px;
      height:38px;
    }

    .v4-overview__context{
      gap:10px;
    }

    .v4-context-card{
      min-height:68px;
      padding:10px 14px;
      border-radius:20px;
    }

    .v4-context-card__icon{
      width:38px;
      height:38px;
    }
  }

  @media(max-width:560px){
    .v4-hero__brand{
      gap:10px;
    }

    .v4-hero__brand-logo{
      width:48px;
      height:48px;
      flex-basis:48px;
    }
  }

`;

