/**
 * Habillage visuel de la vue Eau de Pool Cockpit v4.
 *
 * RÈGLE V4-WATER-STYLE-001 :
 * tous les sélecteurs restent confinés sous `.v4-water`.
 * Ce module ne doit modifier ni la vue d'ensemble ni les autres espaces.
 *
 * RÈGLE V4-WATER-STYLE-002 :
 * la page Eau privilégie une lecture instrumentale et compacte.
 */
const STYLES_EAU_V4 = `

  .v4-water{
    display:grid;
    grid-template-columns:repeat(12,minmax(0,1fr));
    gap:14px;
    padding:20px;
  }

  /* ----------------------------------------------------------
   * En-tête
   * ---------------------------------------------------------- */

  .v4-water>.v4-view__header{
    grid-column:1 / -1;
    margin:0;
    padding:2px 4px 0;
  }

  .v4-water>.v4-view__header>small{
    display:block;
    margin-bottom:4px;
    color:rgba(216,241,255,.72);
    font-size:.66rem;
    font-weight:800;
    letter-spacing:.14em;
    text-transform:uppercase;
  }

  .v4-water>.v4-view__header h1{
    margin:0;
    color:#fff;
    font-size:clamp(2rem,2.6vw,2.75rem);
    font-weight:720;
    letter-spacing:-.045em;
    line-height:1;
  }

  .v4-water>.v4-view__header p{
    margin:7px 0 0;
    max-width:680px;
    color:rgba(224,241,253,.74);
    font-size:.86rem;
  }

  /* ----------------------------------------------------------
   * Synthèse
   * ---------------------------------------------------------- */

  .v4-water__summary{
    grid-column:1 / -1;
    position:relative;
    overflow:hidden;
    min-height:112px;
    padding:20px 24px;
    border:1px solid rgba(178,229,255,.20);
    border-radius:24px;
    background:
      radial-gradient(
        circle at 88% 20%,
        rgba(104,225,241,.20),
        transparent 30%
      ),
      linear-gradient(
        135deg,
        rgba(8,50,101,.78),
        rgba(18,92,132,.56)
      );
    box-shadow:
      0 18px 42px rgba(1,20,48,.20),
      inset 0 1px 0 rgba(255,255,255,.08);
    backdrop-filter:blur(14px);
  }

  .v4-water__summary::after{
    content:"";
    position:absolute;
    right:34px;
    top:50%;
    width:84px;
    height:84px;
    border:1px solid rgba(151,237,248,.30);
    border-radius:50%;
    transform:translateY(-50%);
    box-shadow:
      0 0 0 12px rgba(95,216,236,.055),
      0 0 34px rgba(80,218,239,.14);
    pointer-events:none;
  }

  .v4-water__summary small{
    display:block;
    color:#8ee9f7;
    font-size:.67rem;
    font-weight:800;
    letter-spacing:.12em;
    text-transform:uppercase;
  }

  .v4-water__summary h2{
    margin:6px 0 4px;
    color:#fff;
    font-size:1.55rem;
    font-weight:720;
    letter-spacing:-.035em;
  }

  .v4-water__summary p{
    max-width:760px;
    margin:0;
    color:rgba(226,244,255,.76);
    font-size:.82rem;
    line-height:1.45;
  }

  .v4-water__ai{grid-column:1/-1;display:flex;flex-wrap:wrap;align-items:center;gap:14px;padding:20px 24px;border:1px solid rgba(176,151,255,.48);border-radius:22px;background:linear-gradient(120deg,rgba(49,49,119,.88),rgba(18,79,118,.83));color:#f5f5ff}
  .v4-water__ai>div{flex:1 1 360px;min-width:0}
  .v4-water__ai small{color:#d9cdff;font-weight:800;letter-spacing:.08em;font-size:.67rem}
  .v4-water__ai h2{margin:5px 0;font-size:1.3rem;color:#fff}
  .v4-water__ai p{margin:0;color:#dbe7f6;font-size:.82rem;line-height:1.5;max-width:780px}
  .v4-water__ai button{width:auto!important;min-width:195px;min-height:42px;border:1px solid rgba(222,211,255,.38);border-radius:12px;padding:10px 16px;background:linear-gradient(120deg,#7864df,#4281cf);font-weight:800;color:#fff;cursor:pointer}
  .v4-water__ai-note{flex-basis:100%;font-size:.71rem;color:#c8d6ef}

  /* ----------------------------------------------------------
   * Sections communes
   * ---------------------------------------------------------- */

  .v4-water__section{
    min-width:0;
    padding:18px;
    border:1px solid rgba(177,225,255,.16);
    border-radius:22px;
    background:
      linear-gradient(
        145deg,
        rgba(7,48,96,.74),
        rgba(16,77,120,.58)
      );
    box-shadow:
      0 14px 34px rgba(1,20,48,.16),
      inset 0 1px 0 rgba(255,255,255,.055);
    backdrop-filter:blur(13px);
  }

  .v4-water__section-header{
    margin-bottom:14px;
  }

  .v4-water__section-header small{
    display:block;
    margin-bottom:3px;
    color:rgba(159,227,244,.78);
    font-size:.64rem;
    font-weight:800;
    letter-spacing:.12em;
    text-transform:uppercase;
  }

  .v4-water__section-header h2{
    margin:0;
    color:#fff;
    font-size:1rem;
    font-weight:720;
    letter-spacing:-.025em;
  }

  .v4-water__section p{
    color:rgba(222,240,253,.72);
    font-size:.76rem;
    line-height:1.45;
  }

  /* ----------------------------------------------------------
   * Mesures
   * ---------------------------------------------------------- */

  .v4-water__section:has(.v4-water__metrics){
    grid-column:1 / -1;
  }

  .v4-water__metrics{
    display:grid;
    grid-template-columns:repeat(4,minmax(0,1fr));
    gap:10px;
  }

  .v4-water-metric{
    position:relative;
    min-height:104px;
    padding:15px 16px;
    border:1px solid rgba(155,221,250,.16);
    border-radius:18px;
    background:
      radial-gradient(
        circle at 16% 10%,
        rgba(76,208,240,.12),
        transparent 44%
      ),
      rgba(8,46,94,.56);
    box-shadow:
      inset 0 1px 0 rgba(255,255,255,.05);
  }

  .v4-water-metric small{
    display:block;
    color:rgba(210,235,250,.68);
    font-size:.68rem;
    font-weight:700;
  }

  .v4-water-metric strong{
    display:block;
    margin-top:8px;
    color:#fff;
    font-size:1.75rem;
    font-weight:470;
    letter-spacing:-.055em;
    line-height:1;
  }

  .v4-water-metric__unit{
    margin-left:5px;
    color:rgba(191,226,246,.75);
    font-size:.72rem;
    font-weight:650;
    letter-spacing:0;
  }

  .v4-water-metric__availability{
    position:absolute;
    right:12px;
    bottom:11px;
    color:#8ee6c1;
    font-size:.61rem;
    font-weight:750;
  }

  .v4-water-metric.is-unavailable{
    opacity:.62;
  }

  .v4-water-metric.is-unavailable
  .v4-water-metric__availability{
    color:rgba(226,239,249,.52);
  }

  /* ----------------------------------------------------------
   * Ligne basse : confiance / analyse / traitement
   * ---------------------------------------------------------- */

  .v4-water__confidence{
    grid-column:1 / 5;
  }

  .v4-water__analysis{
    grid-column:5 / 9;
  }

  .v4-water__treatment{
    grid-column:9 / 13;
  }

  .v4-water__confidence>strong{
    display:block;
    margin-top:5px;
    color:#b8f4ff;
    font-size:2.1rem;
    font-weight:500;
    letter-spacing:-.06em;
  }

  .v4-water__confidence>p{
    margin:9px 0 0;
  }

  .v4-water__analysis-score{
    display:flex;
    align-items:flex-end;
    gap:5px;
    margin:3px 0 10px;
  }

  .v4-water__analysis-score strong{
    color:#fff;
    font-size:2rem;
    font-weight:520;
    letter-spacing:-.06em;
    line-height:1;
  }

  .v4-water__analysis-score span{
    padding-bottom:2px;
    color:rgba(213,235,249,.62);
    font-size:.72rem;
  }

  .v4-water__analysis>small{
    display:block;
    margin-top:10px;
    color:rgba(215,235,249,.55);
    font-size:.63rem;
  }

  .v4-water__treatment p{
    margin:6px 0;
  }

  /* ----------------------------------------------------------
   * Actions
   * ---------------------------------------------------------- */

  .v4-water__action{
    min-height:34px;
    margin-top:9px;
    padding:0 16px;
    border:1px solid rgba(151,211,255,.24);
    border-radius:11px;
    color:#fff;
    background:
      linear-gradient(
        135deg,
        rgba(68,139,231,.92),
        rgba(82,104,226,.92)
      );
    box-shadow:0 7px 18px rgba(29,80,184,.18);
    font:inherit;
    font-size:.68rem;
    font-weight:800;
    letter-spacing:.01em;
    cursor:pointer;
  }

  .v4-water__action:disabled{
    cursor:default;
    opacity:.42;
  }

  /* ----------------------------------------------------------
   * Responsive
   * ---------------------------------------------------------- */

  @media(max-width:1000px){
    .v4-water__metrics{
      grid-template-columns:repeat(2,minmax(0,1fr));
    }

    .v4-water__confidence{
      grid-column:1 / 7;
    }

    .v4-water__analysis{
      grid-column:7 / 13;
    }

    .v4-water__treatment{
      grid-column:1 / -1;
    }
  }

  @media(max-width:620px){
    .v4-water{
      display:block;
      padding:16px;
    }

    .v4-water>*+*{
      margin-top:12px;
    }

    .v4-water__summary{
      padding:18px;
    }

    .v4-water__summary::after{
      display:none;
    }

    .v4-water__metrics{
      grid-template-columns:1fr;
    }
  }
`;

