/* Source générée : src/interface/v4/text-contrast-v4.js */
/*
 * SPDX-FileCopyrightText: 2026 Vincent Fournet
 * SPDX-License-Identifier: PolyForm-Noncommercial-1.0.0
 * V4-UX-CONTRAST-01: contrast-only; no events, logic, data-* or layout changes.
 */
const STYLES_CONTRASTE_TEXTE_V4 = `
  /* Ocean/Night: headings over the unmodified pool photograph. */
  .pool-cockpit-v4:not([data-v4-theme="sky"]) .v4-view__header h1,
  .pool-cockpit-v4:not([data-v4-theme="sky"]) .v4-view__header h2 {
    color:#f7fbff;
    text-shadow:0 2px 13px rgba(4,24,51,.85),0 1px 3px rgba(0,12,34,.8);
  }
  .pool-cockpit-v4:not([data-v4-theme="sky"]) .v4-view__header p {
    color:#edf5ff;
    text-shadow:0 2px 9px rgba(2,20,47,.92);
  }
  .pool-cockpit-v4:not([data-v4-theme="sky"]) .v4-view__header > small {
    color:#dcefff;
    text-shadow:0 1px 8px rgba(0,20,48,.9);
  }
  /* Navigation on a light frosted bar: use dark, readable inactive labels. */
  .pool-cockpit-v4[data-v4-theme="ocean"] .v4-navigation__item:not(.is-active),
  .pool-cockpit-v4[data-v4-theme="sky"] .v4-navigation__item:not(.is-active) {
    color:#173b60;
  }
  .pool-cockpit-v4[data-v4-theme="ocean"] .v4-navigation__item:not(.is-active):hover,
  .pool-cockpit-v4[data-v4-theme="sky"] .v4-navigation__item:not(.is-active):hover {
    color:#0b2948;
    background:rgba(255,255,255,.38);
  }
  .pool-cockpit-v4 .v4-navigation__item.is-active { color:#fff; }
  /* Improve only the native V4 glass components; avoid touching V3 controls. */
  .pool-cockpit-v4[data-v4-theme="ocean"] .v4-overview__section-header p,
  .pool-cockpit-v4[data-v4-theme="ocean"] .v4-score__advice {
    color:#e3f0ff;
  }
  .pool-cockpit-v4[data-v4-theme="sky"] .v4-view__header h1,
  .pool-cockpit-v4[data-v4-theme="sky"] .v4-view__header h2 {
    color:#102b48;
    text-shadow:0 1px 8px rgba(255,255,255,.75);
  }
  .pool-cockpit-v4[data-v4-theme="sky"] .v4-view__header p,
  .pool-cockpit-v4[data-v4-theme="sky"] .v4-view__header > small {
    color:#244762;
    text-shadow:0 1px 7px rgba(255,255,255,.75);
  }
  @media (prefers-reduced-motion: reduce) {
    .pool-cockpit-v4 .v4-navigation__item { transition:none; }
  }
`;

