/**
 * Pont d'affichage des éléments fonctionnels V3 dans la V4.
 *
 * RÈGLE V4-LEGACY-001 :
 * aucun data-* fonctionnel V3 n'est renommé.
 *
 * RÈGLE V4-LEGACY-002 :
 * aucune règle métier n'est recalculée.
 *
 * RÈGLE V4-LEGACY-003 :
 * les anciennes sections sont développées dans V4 puisque la navigation
 * principale est désormais assurée par les onglets.
 */

function htmlValide(valeur) {
  return typeof valeur === "string"
    ? valeur.trim()
    : "";
}

/** Réorganise les cartes V3 en V4 sans créer de commande ni dépendre du DOM. */
function restructurerEquipementsV4(html) {
  const debut = /<div\s+class=(?:["']?)rc27-control-grid(?:["']?)>/i.exec(html);
  if (!debut) return html;
  const index = debut.index + debut[0].length;
  const balises = /<\/?div\b[^>]*>/gi;
  balises.lastIndex = index;
  let niveau = 1;
  let fin = -1;
  for (const resultat of html.slice(index).matchAll(/<\/?div\b[^>]*>/gi)) {
    niveau += /^<\/div/i.test(resultat[0]) ? -1 : 1;
    if (!niveau) { fin = index + resultat.index; break; }
  }
  if (fin < 0) return html;
  const contenu = html.slice(index, fin);
  const articles = [...contenu.matchAll(/<article\b[\s\S]*?<\/article>/gi)].map((m) => m[0]);
  if (articles.length < 3) return html;
  const cartes = articles.filter((a) => /class=["'][^"']*(?:rc27-equipment|rc30-pac)[^"']*["']|<h3>[^<]*PAC/i.test(a));
  if (cartes.length < 2) return html;
  const escape = (texte) => String(texte || "").replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
  const extraire = (article, tag) => (article.match(new RegExp(`<${tag}\\b[^>]*>([\\s\\S]*?)<\\/${tag}>`, "i")) || [])[1]?.replace(/<[^>]*>/g, "").trim() || "";
  const resume = cartes.map((article) => `<div class="v4-equipment-status"><strong>${escape(extraire(article, "h3") || "Équipement")}</strong><span>${escape(extraire(article, "b") || "État indisponible")}</span></div>`).join("");
  const autres = articles.filter((article) => !cartes.includes(article));
  const nouvelleGrille = `<section class="v4-equipment-details"><h2>Pilotage et réglages</h2><div class="v4-equipment-controls">${cartes.join("")}</div></section>${autres.length ? `<section class="v4-equipment-extras"><h2>Caméras et autres équipements</h2>${autres.join("")}</section>` : ""}`;
  return html.slice(0, debut.index) + `<div class="rc27-control-grid v4-equipment-layout" data-v4-structured="true">${nouvelleGrille}</div>` + html.slice(fin + 6);
}

function normaliserLegacyComplet(html, onglet = "") {
  let resultat = htmlValide(html);

  if (!resultat) {
    return "";
  }

  /*
   * L'état replié V3 n'est pas pertinent dans la navigation V4.
   */
  resultat = resultat
    .replace(/\bis-collapsed\b/g, "")
    .replace(
      /aria-expanded=(["'])false\1/g,
      'aria-expanded="true"',
    );

  /* Les panneaux de pilotage V3 (<details>) étaient refermés par défaut.
   * Planning et Configuration avancée affichent leur contenu dans la V4
   * sans dépendre du choix de repli mémorisé dans la V3. Aucun état V3
   * n'est écrit ni modifié ; seule la copie HTML est normalisée. */
  if (onglet === "planning" || onglet === "settings") {
    resultat = resultat.replace(
      /<details\b([^>]*\bclass\s*=\s*["'][^"']*\brc27-settings\b[^"']*["'][^>]*)>/gi,
      (original, attributs) => /\sopen(?:\s|=|$)/i.test(attributs)
        ? original
        : `<details${attributs} open>`,
    );
  }

  /*
   * Le <main class="app ..."> historique reste volontairement intact.
   *
   * La racine V4 est un conteneur <div role="main"> : nous pouvons donc
   * conserver exactement le contrat HTML V3 et ses tests historiques.
   */

  // RC6: remove only the redundant recent-analysis card from the V4 History
  // copy. The V3 source renderer, recorded data and other cards stay intact.
  if (onglet === "history") {
    resultat = resultat.replace(
      /<article\s+class=["']v3-info-card v3-history["']>[\s\S]*?<\/article>/i,
      "",
    );
  }

  return onglet === "equipment" ? restructurerEquipementsV4(resultat) : resultat;
}

function rendreLegacyComplet(
  onglet,
  contenu,
) {
  const html =
    normaliserLegacyComplet(contenu, onglet);

  if (!html) {
    return "";
  }

  return `
    <style data-v4-legacy-functional-styles>
      ${STYLES_LEGACY_FUNCTIONAL_V4}
    </style>

    <div
      class="v4-legacy-stage"
      data-v4-legacy-view="${onglet}"
      data-v4-functional-source="v3"
    >
      ${html}
    </div>
  `;
}

function rendreBlocFonctionnel(
  onglet,
  contenu,
) {
  const html = normaliserLegacyComplet(contenu, onglet);

  if (!html) {
    return "";
  }

  return `
    <style data-v4-legacy-functional-styles>${STYLES_LEGACY_FUNCTIONAL_V4}</style>
    <div
      class="v4-functional-legacy"
      data-v4-functional-source="v3"
      data-v4-functional-view="${onglet}"
    >
      ${html}
    </div>
  `;
}

function rendreHistoriqueV3(source = {}) {
  const graphiques =
    source?.graphiques ?? {};

  const temperature =
    htmlValide(graphiques.temperature);

  const ph =
    htmlValide(graphiques.ph);

  const orp =
    htmlValide(graphiques.orp);

  if (!temperature && !ph && !orp) {
    return "";
  }

  return `
    <section
      class="v4-functional-legacy v4-functional-legacy--history"
      data-v4-functional-source="v3"
      data-v4-functional-view="history"
    >
      <div class="v3-charts">
        ${temperature}
        ${ph}
        ${orp}
      </div>
    </section>
  `;
}

function rendreComplementFonctionnelV3V4({
  onglet,
  source = {},
} = {}) {
  /*
   * Dans la vraie carte Home Assistant, on privilégie toujours
   * le rendu complet V3 afin de ne perdre aucune fonctionnalité.
   */
  if (source?.legacyFullHtml) {
    return rendreLegacyComplet(
      onglet,
      source.legacyFullHtml,
    );
  }

  /*
   * Repli utilisé notamment par les previews et tests isolés.
   */
  switch (onglet) {
    case "water":
      return rendreBlocFonctionnel(
        "water",
        source?.legacyHtml,
      );

    case "advice":
      return rendreBlocFonctionnel(
        "advice",
        source?.legacyHtml,
      );

    case "measurements":
      return rendreBlocFonctionnel(
        "measurements",
        source?.legacyHtml,
      );

    case "equipment":
      return rendreBlocFonctionnel(
        "equipment",
        source?.legacyHtml,
      );

    case "planning":
      return rendreBlocFonctionnel(
        "planning",
        source?.legacyHtml,
      );

    case "history":
      return rendreHistoriqueV3(source);

    case "overview":
    default:
      return "";
  }
}

